function Button({ children, variant = "primary", className = "", onClick, type = "button", disabled = false }: { children: React.ReactNode; variant?: "primary" | "secondary" | "ghost" | "soft" | "danger"; className?: string; onClick?: () => void; type?: "button" | "submit"; disabled?: boolean }) {
  return <button type={type} disabled={disabled} className={`btn btn-${variant} ${className}`} onClick={onClick}>{children}</button>;
}

function Tag({ children, tone = "green" }: { children: React.ReactNode; tone?: "green" | "red" | "amber" | "blue" | "neutral" }) {
  return <span className={`tag tag-${tone}`}><span className="tag-dot" />{children}</span>;
}

function MiniSparkline({ color = "#74aa60", points = "0,32 12,30 24,34 36,21 48,26 60,13 72,16 84,8 96,11" }: { color?: string; points?: string }) {
  return <svg className="sparkline" viewBox="0 0 96 40" preserveAspectRatio="none"><polyline fill="none" stroke={color} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" points={points} /></svg>;
}

